create table public.finance_accounts (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, name text not null check(char_length(trim(name))>0), account_type text not null check(account_type in ('cash','bank','digital_wallet','savings','other')), currency text not null default 'ARS' check(char_length(currency)=3), is_active boolean not null default true, created_at timestamptz not null default timezone('utc',now()), updated_at timestamptz not null default timezone('utc',now()), unique(user_id,name));
create table public.finance_categories (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, name text not null check(char_length(trim(name))>0), category_type text not null check(category_type in ('income','expense','both')), is_active boolean not null default true, created_at timestamptz not null default timezone('utc',now()), updated_at timestamptz not null default timezone('utc',now()), unique(user_id,name));
create table public.finance_transactions (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, account_id uuid not null references public.finance_accounts(id) on delete restrict, category_id uuid references public.finance_categories(id) on delete set null, transaction_type text not null check(transaction_type in ('income','expense')), amount numeric not null check(amount>0), status text not null default 'confirmed' check(status in ('pending','confirmed')), occurred_at timestamptz not null default timezone('utc',now()), notes text, created_at timestamptz not null default timezone('utc',now()), updated_at timestamptz not null default timezone('utc',now()));
create index finance_accounts_user_idx on public.finance_accounts(user_id);create index finance_categories_user_idx on public.finance_categories(user_id);create index finance_transactions_user_date_idx on public.finance_transactions(user_id,occurred_at desc);
create function public.validate_finance_transaction() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$ declare account_user uuid;category_user uuid;category_kind text;begin select user_id into account_user from public.finance_accounts where id=new.account_id;if not found or account_user<>new.user_id then raise exception 'La cuenta debe pertenecer al usuario';end if;if new.category_id is not null then select user_id,category_type into category_user,category_kind from public.finance_categories where id=new.category_id;if not found or category_user<>new.user_id or (category_kind<>'both' and category_kind<>new.transaction_type) then raise exception 'La categoría no corresponde al movimiento';end if;end if;return new;end;$$;
create trigger finance_accounts_updated before update on public.finance_accounts for each row execute function public.set_updated_at();create trigger finance_categories_updated before update on public.finance_categories for each row execute function public.set_updated_at();create trigger finance_transactions_updated before update on public.finance_transactions for each row execute function public.set_updated_at();create trigger finance_transactions_validate before insert or update on public.finance_transactions for each row execute function public.validate_finance_transaction();
alter table public.finance_accounts enable row level security;alter table public.finance_categories enable row level security;alter table public.finance_transactions enable row level security;create policy "Users manage own finance accounts" on public.finance_accounts for all to authenticated using((select auth.uid())=user_id)with check((select auth.uid())=user_id);create policy "Users manage own finance categories" on public.finance_categories for all to authenticated using((select auth.uid())=user_id)with check((select auth.uid())=user_id);create policy "Users manage own finance transactions" on public.finance_transactions for all to authenticated using((select auth.uid())=user_id)with check((select auth.uid())=user_id);grant select,insert,update,delete on public.finance_accounts,public.finance_categories,public.finance_transactions to authenticated;
